<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import axios from 'axios'
import CitaForm from '../components/citas/CitaForm.vue'
import CitaTable from '../components/citas/CitaTable.vue'
import { citaService, mensajeErrorCita } from '../Services/citaService.js'
import '../assets/styles/citas.css'
const citas=ref([]), meta=ref({current_page:1,last_page:1,total:0}), catalogos=ref({pacientes:[],sucursales:[],colaboradores:[],especialidades:[]}), loading=ref(false), loadingCatalogos=ref(false), busy=ref(false), error=ref(''), catalogError=ref(''), toast=ref(null), filters=ref({texto:'',Estado:''}), activeFilters=ref({}), selected=ref(null), mode=ref(''), fieldErrors=ref({}), dialogError=ref(''), modal=ref(null)
let toastTimer, alive=true
const locked=computed(()=>loading.value||busy.value)
function notify(message,kind='success'){clearTimeout(toastTimer);toast.value={message,kind};toastTimer=setTimeout(()=>toast.value=null,5000)}
function extractList(response){ if(Array.isArray(response)) return response; return response?.data || response?.datos || [] }
async function loadCatalogos(){loadingCatalogos.value=true;catalogError.value='';try{const [c,p,s]=await Promise.all([citaService.catalogos(),citaService.pacientes(),citaService.sucursales()]);if(!alive)return;catalogos.value={colaboradores:extractList(c.colaboradores),especialidades:extractList(c.especialidades),pacientes:extractList(p),sucursales:extractList(s)};if(Object.values(catalogos.value).some(x=>!x.length))catalogError.value='Hay catálogos sin registros. Verifica pacientes, sucursales, colaboradores y especialidades.'}catch(e){if(alive){catalogError.value=mensajeErrorCita(e);notify(catalogError.value,'error')}}finally{if(alive)loadingCatalogos.value=false}}
async function load(page=1){loading.value=true;error.value='';try{const params={...activeFilters.value,page,per_page:15};const result=Object.keys(activeFilters.value).length?await citaService.buscar(params):await citaService.listar(params);if(!alive)return;citas.value=result.data||[];meta.value=result.meta||{current_page:1,last_page:1,total:citas.value.length}}catch(e){if(alive&&!axios.isCancel(e)){citas.value=[];error.value=mensajeErrorCita(e)}}finally{if(alive)loading.value=false}}
function search(){activeFilters.value=Object.fromEntries(Object.entries(filters.value).map(([k,v])=>[k,v.trim()]).filter(([,v])=>v));load(1)}function clearSearch(){filters.value={texto:'',Estado:''};activeFilters.value={};load(1)}
async function open(kind,row=null){if(locked.value)return;busy.value=true;dialogError.value='';fieldErrors.value={};try{selected.value=(kind==='edit'||kind==='consult'||kind==='delete')?await citaService.obtener(row.id):null;mode.value=kind;modal.value?.showModal()}catch(e){notify(mensajeErrorCita(e),'error')}finally{busy.value=false}}
function close(){if(!busy.value)modal.value?.close()}function closed(){mode.value='';selected.value=null;dialogError.value='';fieldErrors.value={}}
async function save(payload){busy.value=true;dialogError.value='';fieldErrors.value={};try{if(selected.value)await citaService.actualizar(selected.value.id,payload);else await citaService.crear(payload);if(!alive)return;notify(selected.value?'Cita actualizada correctamente.':'Cita agregada correctamente.');modal.value?.close();await load(meta.value.current_page)}catch(e){if(alive){dialogError.value=mensajeErrorCita(e);fieldErrors.value=e.response?.data?.errors||{};notify(dialogError.value,'error')}}finally{if(alive)busy.value=false}}
async function remove(){if(!selected.value||busy.value)return;if(!window.confirm(`¿Eliminar la cita del ${selected.value.FechaHoraCita ? new Date(selected.value.FechaHoraCita).toLocaleString() : 'fecha no indicada'}? También se eliminarán sus detalles.`))return;busy.value=true;try{await citaService.eliminar(selected.value.id);if(!alive)return;notify('Cita eliminada.');modal.value?.close();await load(meta.value.current_page)}catch(e){if(alive){dialogError.value=mensajeErrorCita(e);notify(dialogError.value,'error')}}finally{if(alive)busy.value=false}}
onMounted(()=>{loadCatalogos();load()});onBeforeUnmount(()=>{alive=false;clearTimeout(toastTimer)})
</script>
<template><main class="page cita-module"><header class="page-header"><div><p class="eyebrow">Sanatorio Médico</p><h1>Citas y consultas</h1><p class="cita-muted">Administra citas, referencias y el detalle de cada consulta.</p></div><button class="cita-primary" :disabled="locked" @click="open('create')">+ Agregar cita</button></header>
<form class="cita-card cita-search" @submit.prevent="search"><h2>Buscar citas</h2><div class="cita-search-grid"><label>Texto<input v-model="filters.texto" maxlength="1000" placeholder="Motivo, síntomas o tipo de atención" :disabled="locked"></label><label>Estado<select v-model="filters.Estado" :disabled="locked"><option value="">Todos</option><option>Programada</option><option>Confirmada</option><option>En curso</option><option>Atendida</option><option>Cancelada</option><option>No asistió</option></select></label></div><div class="cita-form-actions"><button class="cita-primary" :disabled="locked">Buscar</button><button type="button" :disabled="locked" @click="clearSearch">Limpiar</button><button type="button" :disabled="locked" @click="load(meta.current_page)">Actualizar</button></div></form>
<p v-if="error" class="cita-error" role="alert">{{ error }}</p><p class="cita-muted" role="status">{{ loading?'Cargando citas…':`${meta.total||0} citas encontradas` }}<span v-if="loadingCatalogos"> · Cargando catálogos…</span></p><CitaTable :citas="citas" :busy="locked" @consult="open('consult',$event)" @edit="open('edit',$event)" @delete="open('delete',$event)"/>
<nav class="cita-pagination"><span>Página {{ meta.current_page }} de {{ meta.last_page }}</span><div><button :disabled="locked||meta.current_page<=1" @click="load(meta.current_page-1)">Anterior</button><button :disabled="locked||meta.current_page>=meta.last_page" @click="load(meta.current_page+1)">Siguiente</button></div></nav>
<dialog ref="modal" class="cita-dialog" @cancel="busy?$event.preventDefault():null" @close="closed"><template v-if="mode"><h2>{{ {create:'Agregar cita',edit:'Editar cita',consult:'Consultar cita',delete:'Eliminar cita'}[mode] }}</h2><p v-if="dialogError" class="cita-error" role="alert">{{ dialogError }}</p><p v-if="catalogError" class="cita-note">{{ catalogError }}</p><CitaForm v-if="['create','edit','consult'].includes(mode)" :key="`${mode}-${selected?.id||'new'}`" :cita="selected" :catalogos="catalogos" :loading-catalogos="loadingCatalogos" :catalog-error="catalogError" :busy="busy" :errors="fieldErrors" :readonly="mode==='consult'" @save="save" @cancel="close"/><template v-else><p>¿Eliminar esta cita y todos sus detalles asociados? Esta acción no se puede deshacer.</p><div class="cita-form-actions"><button :disabled="busy" @click="close">Cancelar</button><button class="cita-danger" :disabled="busy" @click="remove">{{ busy?'Eliminando…':'Confirmar eliminación' }}</button></div></template></template></dialog>
<div v-if="toast" class="cita-toast" :class="{'is-error':toast.kind==='error'}" role="status" aria-live="polite"><span>{{ toast.message }}</span><button aria-label="Cerrar mensaje" @click="toast=null">×</button></div></main></template>
